 * 
 * Example 2:
 * 
 * Input: intersectVal = 2, listA = [1,9,1,2,4], listB = [3,2,4], skipA = 3, skipB = 1
 * Output: Reference of the node with value = 2
 * Input Explanation: The intersected node's value is 2 (note that this must not be 0 if the two lists 
 * intersect). From the head of A, it reads as [1,9,1,2,4]. From the head of B, it reads as [3,2,4]. 
 * There are 3 nodes before the intersected node in A; There are 1 node before the intersected node in 
 * B.
 * 
 * Example 3:
 * 
 * Input: intersectVal = 0, listA = [2,6,4], listB = [1,5], skipA = 3, skipB = 2
 * Output: null
 * Input Explanation: From the head of A, it reads as [2,6,4]. From the head of B, it reads as [1,5]. 
 * Since the two lists do not intersect, intersectVal must be 0, while skipA and skipB can be 
 * arbitrary values.
 * Explanation: The two lists do not intersect, so return null.
 * 
 * Notes:
 * 
 * 	If the two linked lists have no intersection at all, return null.
 * 	The linked lists must retain their original structure after the function returns.
 * 	You may assume there are no cycles anywhere in the entire linked structure.
 * 	Each value on each linked list is in the range [1, 10^9].
 * 	Your code should preferably run in O(n) time and use only O(1) memory.
 ******************************************************************************************************/

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode(int x) {
 *         val = x;
 *         next = null;
 *     }
 * }
 */
public class Solution {
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        if (headA == null || headB == null) {
            return null;
        }

        var lenA = getLength(headA);
        var lenB = getLength(headB);

        if (lenA > lenB) {
            var diff = lenA - lenB;
            while (diff-- > 0) {
                headA = headA.next;
            }
        } else {
            var diff = lenB - lenA;
            while (diff-- > 0) {
                headB = headB.next;
            }
        }

        while (headA != null && headB != null) {
            if (headA == headB) {
                return headA;
            }
            headA = headA.next;
            headB = headB.next;
        }

        return null;
    }

    int getLength(ListNode head) {
        var len = 0;
        while (head != null) {
            len++;
            head = head.next;
        }

        return len;
    }
}

